raw:
{
  "spells": [
    {
      "id": "spell_wind_04",
      "theory": "听风术把少量魔力送入近处空气，让气流在碰到石面、木墙或人体时带回细微回声。施术者用耳廓与掌心共同分辨这些回声，从而判断风向、风速以及三米内是否有遮挡。石墙密实，回声被挡在另一侧，所以术法无法穿墙；它也不产生声音，只是把已有气流的动静放大给施术者。",
      "casting": "拇指与食指相触成环，贴近耳侧，另掌朝风向摊开，屏息两三次，让掌心感到气流经过。",
      "failure": "若呼吸未稳，回声会混成一片嗡鸣，风感错乱，甚至把远处无关的气流误认为近处来风，需重新静立再试。",
      "counters": [
        "在施术者近旁烧湿草，浓烟可搅乱气流回声，使其分辨不清。",
        "用厚毡或木板挡在施术者与目标方向之间，可截断近处气流。"
      ],
      "socialConsequences": "河谷乡民常请懂得听风的人查看晾谷场或渡口的风向，但不允许陌生人贴着他人住宅外墙施术，以免窥探院内动静。城中公会鼓励在公开集市使用，却要求施术者不得故意对准他人窗口。港口船主会雇人听风判断是否适合出航，而搬运工担心风向被船主独占，影响当日卸货安排。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把远处风声误作近处来风，需反复静立确认。",
        "熟练后能稳定分辨三米内的风向与大致风速。",
        "更精者可在嘈杂环境中抓出墙角的微弱回旋气流。",
        "极精者能凭气流回声判断薄帘后是否有人静立。"
      ]
    },
    {
      "id": "spell_wind_05",
      "theory": "晾谷风以魔力推动谷堆表层空气缓慢流动，使湿气从谷粒缝隙间散出。施术者并不翻动谷物，只是让风贴着谷堆表面和浅层缝隙循环，带走水汽。谷物内部仍靠人力翻晒才能彻底干燥，术法只帮助表层排湿，不能替代翻谷、扬谷或仓储检查。范围十米，超出后风势消散。",
      "casting": "双手从谷堆底部缓缓上抬，掌心朝内画两个半圆，再向两侧轻轻推开，如同分开一层薄雾。",
      "failure": "若手势过快，风会只吹走表层干谷，留下湿谷结块，甚至把谷壳吹散到远处，造成无谓损失。",
      "counters": [
        "用草席或厚布覆盖谷堆，可隔断表层气流循环。",
        "在谷堆旁洒水增加空气湿度，能使排湿效果明显减弱。"
      ],
      "socialConsequences": "河谷农户在秋收时欢迎这种风，但乡约要求施术者先取得谷堆主人同意，避免把别家谷壳吹进邻田。城中粮商愿意付钱请人处理受潮存货，却要承担翻谷人工照旧。港口货栈担心湿谷在装船前被误判为已干，因此要求施术者与验货人同时在场见证。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常只吹动表层干谷，湿气仍留在浅层缝隙。",
        "熟练后能均匀带动十米内谷堆表层空气，排湿较稳。",
        "更精者能避开谷壳轻处，减少不必要的吹散损失。",
        "极精者可在不翻动谷粒的情况下让表层湿度趋于一致。"
      ]
    },
    {
      "id": "spell_wind_06",
      "theory": "缓坠术在目标身体周围维持一层上升气流，使下落速度减慢到可以调整姿势的程度。魔力只对单个活物生效，不能托住麻袋、木箱或铁器；若目标携带重物，重物仍按原速下坠并可能拉偏身体。术法持续约一分钟，足够从低处平台或船桅中段安全落地，但无法从极高处无伤坠落。",
      "casting": "施术者伸出一掌朝下，另一手在胸前画螺旋，同时用短促口令让目标放松身体，气流便从脚底升起。",
      "failure": "螺旋画反会使气流从头顶压下，目标反而加速下坠；魔力中断则缓坠骤然消失，目标会重重落地。",
      "counters": [
        "在目标身上系重物，可抵消部分上升气流，使其下坠加快。",
        "用强风从侧面吹偏目标，可破坏螺旋气流的稳定结构。"
      ],
      "socialConsequences": "河谷渡口工头允许工人用缓坠术从低处货台跳下，但要求先检查下方无人。城中公会要求施术者对非自愿目标负责，若用于把人从窗口推下则按伤害罪追究。港口船主欢迎它减少桅杆摔伤，但搬运工担心雇主借此省去安全绳，要求仍保留人工防护。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常因螺旋画不稳导致目标左右摇晃。",
        "熟练后能让单个活物从三米内平台平稳落地。",
        "更精者可微调气流，使目标在落地前保持直立。",
        "极精者能在目标携带轻物时仍维持缓坠，重物仍会拉偏。"
      ]
    }
  ]
}
